export default function FrancisXavier({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        <rect
          x="0"
          y="0"
          width="1086"
          height="1448"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open sky / distant scene base. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1086" height="1448" />
        </g>

        {/* Cloud banks and small drifting clouds. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} fillRule="evenodd" />
        </g>

        {/* Double halo ring behind St. Francis Xavier. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} fillRule="evenodd" />
        </g>

        {/* Ship, sea, island, shrubs, and distant landscape symbols. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} fillRule="evenodd" />
        </g>

        {/* Main cassock and lower inner garment shapes. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} fillRule="evenodd" />
        </g>

        {/* Outer drape, shoulder mantle, side folds, and broad sleeves. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} fillRule="evenodd" />
        </g>

        {/* Crucifix wood, corpus, and the closed book with the IHS emblem. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} fillRule="evenodd" />
        </g>

        {/* Face, neck, and both visible hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} fillRule="evenodd" />
        </g>

        {/* Head hair, eyebrows, moustache, and beard. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} fillRule="evenodd" />
        </g>

        {/* Exact traced black line art from the supplied Francis Xavier image.
            Keep this last and non-interactive. */}
        <path
          {...detail}
          {...ink}
          d={FRANCIS_XAVIER_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}